function surface(input) {
  const u = input.u;
  const v = input.v;

  const g = input.g;                 // product law
  //const n = Math.max(1, Math.min(5, Math.floor(input.n)));
  const n = Math.max(1, Math.min(5, Math.floor(3)));

  const N = 1 << n;
  const sq = Array.from({ length: n }, () => 1);

  // ---- helpers ----
  function popcount(x) {
    let c = 0;
    while (x) { x &= (x - 1); c++; }
    return c;
  }

  function swapsParity(A, B) {
    let parity = 0;
    for (let i = 0; i < n; i++) {
      if ((A >>> i) & 1) {
        const belowMask = (1 << i) - 1;
        parity ^= (popcount(B & belowMask) & 1);
      }
    }
    return parity;
  }

  function omega(A, B) {
    const sgn = swapsParity(A, B) ? -1 : 1;
    return sgn; // metric all +1
  }

  function multiply(F, G) {
    const H = new Float64Array(N);
    for (let U = 0; U < N; U++) {
      let sum = 0;
      for (let A = 0; A < N; A++) {
        const B = A ^ U;
        const coeff = (1 - g) + g * omega(A, B);
        sum += F[A] * G[B] * coeff;
      }
      H[U] = sum;
    }
    return H;
  }

  function l2norm(F) {
    let s = 0;
    for (let i = 0; i < N; i++) s += F[i] * F[i];
    return Math.sqrt(s);
  }

  function support(F) {
    let c = 0;
    for (let i = 0; i < N; i++) if (Math.abs(F[i]) > 1e-6) c++;
    return c;
  }

  // ---- seed multivector F0 ----
  const A0 = Math.floor(u * N);
  const B0 = Math.floor(v * N);

  const F0 = new Float64Array(N);
  F0[A0] = Math.sin(2 * Math.PI * u);
  F0[B0] += Math.cos(2 * Math.PI * v);

  // ---- true computation depth from t ----
  const maxSteps = 12;
  const depth = input.t * maxSteps;

  const k = Math.floor(depth);
  const frac = depth - k;

  let F = new Float64Array(N);
  F[0] = 1; // identity start

  for (let i = 0; i < k; i++) {
    F = multiply(F, F0);
  }

  const Fnext = multiply(F, F0);

  // interpolate between step k and k+1
  const Finterp = new Float64Array(N);
  for (let i = 0; i < N; i++) {
    Finterp[i] = (1 - frac) * F[i] + frac * Fnext[i];
  }

  const normF = l2norm(Finterp);
  const supp = support(Finterp);

  // ---- geometry ----
  const angleA = 2 * Math.PI * u;
  const angleB = 2 * Math.PI * v;

  const baseR = 1.1;
  const R = baseR + 0.9 * (supp / N);

  const tubeR = 0.3 + 0.1 * Math.tanh(depth);

  const x = (R + tubeR * Math.cos(angleB)) * Math.cos(angleA);
  const y = (R + tubeR * Math.cos(angleB)) * Math.sin(angleA);
  const z = Math.log(1 + normF);

  // color: red = geometric growth, blue = convolution
  const r = Math.min(1, 0.2 + 0.8 * g);
  const b = Math.min(1, 0.2 + 0.8 * (1 - g));
  const gg = Math.min(1, 0.1 + 0.9 * (supp / N));

  return { x, y, z, r, g: gg, b, a: 1.0 };
}
